function validate([s1, s2]) {
  if (typeof s1 !== 'string' || s1.length < 1 || s1.length > 20) return 's1 needs 1 to 20 characters.';
  if (typeof s2 !== 'string' || s2.length !== s1.length) return 's2 must be as long as s1.';
  if (!/^[a-f]+$/.test(s1) || !/^[a-f]+$/.test(s2)) return 'Only the letters a to f are allowed.';
  if ([...s1].sort().join('') !== [...s2].sort().join('')) return 's2 must be an anagram of s1.';
  return null;
}

