function kSimilarity(s1, s2) {
  const n = s1.length;
  const seen = new Set([s1]);
  let queue = [s1];
  let swaps = 0;

  while (queue.length > 0) {
    const next = [];
    for (const current of queue) {
      if (current === s2) {
        return swaps;
      }
      let i = 0;
      while (current[i] === s2[i]) {
        i++;
      }
      const chars = current.split('');
      for (let j = i + 1; j < n; j++) {
        if (chars[j] !== s2[i] || chars[j] === s2[j]) {
          continue;
        }
        [chars[i], chars[j]] = [chars[j], chars[i]];
        const candidate = chars.join('');
        if (!seen.has(candidate)) {
          seen.add(candidate);
          next.push(candidate);
        }
        [chars[i], chars[j]] = [chars[j], chars[i]];
      }
    }
    queue = next;
    swaps++;
  }
  return -1;
}

