function kSimilarity(s1, s2) {
  // Each wrong position is an edge from the letter it holds to the letter it needs. The edges split into cycles,
  // a cycle of L edges costs L - 1 exchanges, so the answer is the wrong positions minus the most cycles in a split.
  const letters = 'abcdef';
  const count = Array.from({ length: 6 }, () => new Array(6).fill(0));
  let wrong = 0;
  for (let p = 0; p < s1.length; p++) {
    if (s1[p] !== s2[p]) { count[letters.indexOf(s1[p])][letters.indexOf(s2[p])]++; wrong++; }
  }
  const memo = new Map();
  const most = () => {
    const key = count.join(';');
    if (memo.has(key)) return memo.get(key);
    let start = -1, first = -1;
    for (let u = 0; u < 6 && start < 0; u++) for (let v = 0; v < 6; v++) if (count[u][v] > 0) { start = u; first = v; break; }
    if (start < 0) return 0;
    // Every split puts this edge in some simple cycle; try each one and recurse on the rest.
    const visited = new Set([start]);
    let best = 0;
    const walk = node => {
      if (node === start) { best = Math.max(best, 1 + most()); return; }
      visited.add(node);
      for (let v = 0; v < 6; v++) {
        if (count[node][v] > 0 && (v === start || !visited.has(v))) { count[node][v]--; walk(v); count[node][v]++; }
      }
      visited.delete(node);
    };
    count[start][first]--; walk(first); count[start][first]++;
    memo.set(key, best);
    return best;
  };
  return wrong - most();
}

