function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const n = size === 'large' ? 14 + pick(7) : 1 + pick(7);
  const alphabet = 'abcdef'.slice(0, 1 + pick(6));
  const first = Array.from({ length: n }, () => alphabet[pick(alphabet.length)]);
  const second = [...first];
  if (rand() < 0.3) {
    // A few random exchanges keep the answer small.
    const moves = pick(n);
    for (let m = 0; m < moves; m++) { const a = pick(n), b = pick(n); [second[a], second[b]] = [second[b], second[a]]; }
  } else {
    for (let i = n - 1; i > 0; i--) { const j = pick(i + 1); [second[i], second[j]] = [second[j], second[i]]; }
  }
  return [first.join(''), second.join('')];
}
